<?php session_start();require '../config/db.php';if(!isset($_SESSION['admin'])){header('Location: login.php');exit;}if(isset($_GET['action'],$_GET['id'])){$id=(int)$_GET['id'];$q=$pdo->prepare($_GET['action']==='publish'?"UPDATE stories SET status='published',published_at=NOW() WHERE id=?":"UPDATE stories SET status='rejected' WHERE id=?");$q->execute([$id]);header('Location: dashboard.php');exit;}$stories=$pdo->query("SELECT * FROM stories ORDER BY created_at DESC")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DailyPost Admin</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header><a class="brand" href="../index.php">Daily<span>Post</span></a><nav><a href="logout.php">Logout</a></nav></header><main><section class="section"><h1>Submissions</h1><p>100 demo stories are seeded as published. New visitor submissions appear as pending.</p><?php foreach($stories as $s):?><article class="admin-card"><b><?=htmlspecialchars($s['title'])?></b><span>By <?=htmlspecialchars($s['author'])?> · <?=htmlspecialchars($s['status'])?></span><p><?=htmlspecialchars(mb_substr($s['body'],0,200))?>…</p><?php if($s['status']==='pending'):?><a class="button" href="?action=publish&id=<?=$s['id']?>">Publish</a> <a class="button danger" href="?action=reject&id=<?=$s['id']?>">Reject</a><?php endif;?></article><?php endforeach;?></section></main></body></html>